# Change the sheet's today: the date every date decision and default date in the sheet uses.
guard:
  class: net.officefloor.hq.app.settings.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.sheet.ValidateToday
  next: save
save:
  class: net.officefloor.hq.app.sheet.SaveSheetToday
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
# Close a period: fix its due-total as it is now. A closed period cannot be closed again.
guard:
  class: net.officefloor.hq.app.settings.RefuseViewer
  next: close
close:
  class: net.officefloor.hq.app.period.ClosePeriod
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveSheetToday {
    public void save(@PathVariable("sheetId") String sheetId, @Val LocalDate today,
            ServerHttpConnection connection, SheetRepository repository, Rollup rollup, Out<Sheet> sheet)
            throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        Rollup.Snapshot before = rollup.take(id);
        if (!repository.setToday(id, today)) {
            throw new BadRequestException("no such sheet");
        }
        rollup.record(id, by, before);
        sheet.set(new Sheet(id, today.toString()));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Hold;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.settings.SettingsRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Close a period, by a role the sheet's permission matrix allows (by default a clerk or a steward): fix its due-total as shown now (the dues now, late charges included, of the claims dated in it that count by
 *  the status they had at the end of its last day, a person's
 *  open (OPEN or PENDING) claims dated within one of their holds left out unless bound by a statement,
 *  skipping those with none), so later changes to rates do not alter it; and each person's due-total for it
 *  likewise, for every person on the sheet (0.00 for one with nothing in it). */
public class ClosePeriod {
    public void close(@PathVariable("sheetId") String sheetId, @PathVariable("periodName") String periodName,
            ServerHttpConnection connection, PeriodRepository repository, ClaimRepository claims, PersonRepository people, SettingsRepository settings,
            Audit audit, Out<Period> period) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.lockSheet(id)) {
            throw new BadRequestException("no such sheet");
        }
        Period found = repository.find(id, periodName == null ? "" : periodName.trim());
        if (found == null) {
            throw new BadRequestException("no such period");
        }
        if (!settings.allows(id, "close", by)) {
            throw new BadRequestException("a " + settings.role(id, by) + " cannot close a period");
        }
        if (found.closed()) {
            throw new BadRequestException("the period " + found.name() + " is already closed");
        }
        LocalDate from = LocalDate.parse(found.from());
        LocalDate to = LocalDate.parse(found.to());
        Map<Long, List<Hold>> holds = people.holds(id);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
        for (Person p : people.list(id)) personTotals.put(p.id(), BigDecimal.ZERO.setScale(2));
        Map<Long, String> statusesThen = claims.statusesOn(id, to);
        String today = repository.today(id);
        for (Claim c : claims.list(id)) {
            LocalDate on = LocalDate.parse(c.date());
            if (on.isBefore(from) || on.isAfter(to)
                    || !c.countsAs(statusesThen.get(c.id()), holds.getOrDefault(c.personId(), List.of()), today)) continue;
            BigDecimal now = claims.dueNow(id, c);
            if (now != null) {
                total = total.add(now);
                personTotals.merge(c.personId(), now, BigDecimal::add);
            }
        }
        String shown = total.setScale(2).toPlainString();
        repository.close(id, found.id(), total, personTotals);
        audit.record("PERIOD_CLOSED sheet=" + id + " by=" + by + " period=" + found.name() + " total=" + shown);
        period.set(new Period(found.id(), found.name(), found.from(), found.to(), true, shown, personTotals.entrySet().stream().collect(Collectors.toMap(e -> Long.toString(e.getKey()),
                e -> e.getValue().setScale(2).toPlainString(), (a, b) -> a, LinkedHashMap::new))));
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import net.officefloor.hq.app.BadRequestException;

/** Refuse a change to a claim dated inside a closed period. */
public final class PeriodGuard {
    private PeriodGuard() {
    }

    public static void open(PeriodRepository periods, String sheetId, LocalDate date) throws BadRequestException {
        String closed = periods.closedOn(sheetId, date);
        if (closed != null) {
            throw new BadRequestException("the period " + closed + " is closed");
        }
    }
}
